    sourceSets["main"].kotlin.directories.add("generated/valdi")
    namespace = "io.valdiroutes.app"
    compileSdk = 37
    // The vision vendor archives (vision/vendor/install/android-arm64) were built with NDK r27.1 and c++_shared.
    ndkVersion = "27.1.12297006"

    defaultConfig {
        applicationId = "io.valdiroutes.app"
        minSdk = 28
        targetSdk = 37
        versionCode = 1
        versionName = "0.1"
        // The aar carries arm32/arm64/x86_64; the demo only ships arm64.
        ndk { abiFilters += "arm64-v8a" }
        externalNativeBuild {
            cmake {
                arguments += listOf("-DANDROID_STL=c++_shared", "-DANDROID_SUPPORT_FLEXIBLE_PAGE_SIZES=ON")
                cppFlags += listOf("-std=c++20", "-fexceptions", "-frtti")
            }
        }
    }
    // OpenCV mobile + ncnn behind VisionHost; see src/main/cpp/CMakeLists.txt.
    externalNativeBuild {
        cmake {
            path = file("src/main/cpp/CMakeLists.txt")
            version = "3.22.1"
        }
    }

    buildTypes {
        release {
            // R8 rules: Valdi's come with valdi_runtime.aar (proguard.txt); the app's own are in proguard-rules.pro.
            isMinifyEnabled = true
            isShrinkResources = true
            proguardFiles(getDefaultProguardFile("proguard-android-optimize.txt"), "proguard-rules.pro")
            // Local demo builds only; production signing belongs to the consuming app.
            signingConfig = signingConfigs.getByName("debug")
        }
    }
    compileOptions {
        sourceCompatibility = JavaVersion.VERSION_17
        targetCompatibility = JavaVersion.VERSION_17
    }
    buildFeatures { compose = true }
}

