/**
 * valdi_ota.json in the app's assets (ValdiOta.kt), from scripts/ota.mjs app-info: the app version packages target,
 * this binary's fingerprint (the export's Valdi half in libs/valdi_ota.json, the Kotlin bindings in generated/valdi,
 * the native files listed in ota/fingerprint.json), the update server and the key packages are signed with. A release
 * build with updates on records the fingerprint as its version's (ota/releases/android/<versionName>.json), or fails
 * when that version was released with another: see scripts/ota.mjs. Runs `node` from the PATH Gradle was started with.
 */
abstract class ValdiOtaInfo : DefaultTask() {
    @get:InputFile abstract val exportInfo: RegularFileProperty
    /** What the fingerprint hashes besides the export info: ota.mjs, ota/fingerprint.json and what it lists, the bindings. */
    @get:InputFiles @get:PathSensitive(PathSensitivity.RELATIVE) abstract val fingerprintFiles: ConfigurableFileCollection
    @get:Internal abstract val repoRoot: DirectoryProperty
    @get:InputFile abstract val publicKey: RegularFileProperty
    @get:Input abstract val appVersion: Property<String>
    @get:Input abstract val updateUrl: Property<String>
    /** The release record, when this build makes one: an output, so the task runs again when it's removed or edited. */
    @get:Optional @get:OutputFile abstract val releaseRecord: RegularFileProperty
    @get:OutputDirectory abstract val outputDir: DirectoryProperty
    @get:Inject abstract val execOperations: ExecOperations

    @TaskAction
    fun write() {
        val out = ByteArrayOutputStream()
        execOperations.exec {
            commandLine(
                listOf(
                    "node", repoRoot.get().asFile.resolve("scripts/ota.mjs").path, "app-info", "android",
                    exportInfo.get().asFile.path, appVersion.get(), updateUrl.get(),
                ) + if (releaseRecord.isPresent) listOf("--record") else emptyList(),
            )
            standardOutput = out
        }
        outputDir.get().asFile.resolve("valdi_ota.json").writeText(out.toString().trim())
    }
}

/**
 * The Valdi modules tools/valdi-rolldown builds (app_pages, and the npm packages it bundles) as assets: JavaScript with
 * inline source maps in debug builds, Hermes bytecode and <module>.map.json in release builds, as Valdi ships them;
 * and app_pages' res/ images as drawables. scripts/export-android.sh leaves the modules out of the aar. Runs `pnpm`
 * through scripts/pnpm.mjs on Windows, or pnpm from the PATH elsewhere.
 */
abstract class ValdiModules : DefaultTask() {
    @get:InputFiles @get:PathSensitive(PathSensitivity.RELATIVE) abstract val sources: ConfigurableFileCollection
    @get:Input abstract val release: Property<Boolean>
    @get:Input abstract val pnpm: ListProperty<String>
    @get:Internal abstract val toolDir: DirectoryProperty
    @get:OutputDirectory abstract val outputDir: DirectoryProperty
    @get:OutputDirectory abstract val resDir: DirectoryProperty
    @get:Inject abstract val execOperations: ExecOperations

    @TaskAction
    fun build() {
        val out = outputDir.get().asFile
        out.deleteRecursively()
        val mode = if (release.get()) listOf("--release") else emptyList()
        execOperations.exec {
            workingDir = toolDir.get().asFile
            commandLine(pnpm.get() + listOf("exec", "tsx", "build.ts", "--out", out.path, "--res", resDir.get().asFile.path) + mode)
        }
    }
}

/**
 * Fails when generated/valdi (Kotlin) or valdi/native/generated (C++) is not what tools/valdi-rolldown/codegen.ts
 * generates from the current TypeScript: a native interface changed without the bindings being regenerated. Only
 * checks; regenerating is done by hand. The C++ is linked into the exported runtime, so it also fails when valdi/native
 * changed since libs/valdi_runtime.aar was exported (scripts/ota.mjs check-export).
 */
abstract class ValdiCodegenCheck : DefaultTask() {
    @get:InputFiles @get:PathSensitive(PathSensitivity.RELATIVE) abstract val sources: ConfigurableFileCollection
    @get:Input abstract val pnpm: ListProperty<String>
    @get:Internal abstract val repoDir: DirectoryProperty
    @get:Internal abstract val generatedDir: DirectoryProperty
    @get:Internal abstract val exportInfo: RegularFileProperty
    @get:OutputFile abstract val stamp: RegularFileProperty
    @get:Inject abstract val execOperations: ExecOperations

    @TaskAction
    fun check() {
        val repo = repoDir.get().asFile
        val cppDir = repo.resolve("valdi/native/generated")
        val result = execOperations.exec {
            workingDir = repo.resolve("tools/valdi-rolldown")
            commandLine(
                pnpm.get() + listOf(
                    "exec", "tsx", "codegen.ts",
                    "--kotlin-out", generatedDir.get().asFile.path, "--cpp-out", cppDir.path, "--check",
                ),
            )
            isIgnoreExitValue = true
        }
        if (result.exitValue != 0) {
            throw GradleException(
                "The Valdi bindings in generated/valdi or valdi/native/generated are stale: a native interface changed. " +
                    "Regenerate them with\n" +
                    "  cd tools/valdi-rolldown && pnpm exec tsx codegen.ts --kotlin-out ../../android/app/generated/valdi " +
                    "--cpp-out ../../valdi/native/generated\n" +
                    "then export the runtime again (scripts/export-android.sh): the C++ is linked into it.",
            )
        }
        execOperations.exec {
            commandLine("node", repo.resolve("scripts/ota.mjs").path, "check-export", "android", exportInfo.get().asFile.path)
        }
        stamp.get().asFile.writeText("ok")
    }
}

val valdiCodegenCheck = tasks.register<ValdiCodegenCheck>("valdiCodegenCheck") {
    val repo = rootProject.projectDir.parentFile
    val tool = repo.resolve("tools/valdi-rolldown")
    sources.from(
        fileTree(repo.resolve("valdi/modules")) { include("*/src/**", "*/tsconfig.json", "*/module.json") },
        fileTree(tool) { include("codegen.ts", "codegen/**", "vendor/**", "valdiTs.ts", "pipeline.ts", "package.json", "pnpm-lock.yaml") },
        fileTree("generated/valdi"),
        fileTree(repo.resolve("valdi/native")),
        file("libs/valdi_ota.json"),
    )
    pnpm = providers.gradleProperty("valdiPnpm").map { listOf(it) }.orElse(
        if (System.getProperty("os.name").startsWith("Windows", ignoreCase = true)) {
            listOf("node", repo.resolve("scripts/pnpm.mjs").path)
        } else {
            listOf("pnpm")
        },
    )
    repoDir = repo
    generatedDir = file("generated/valdi")
    exportInfo = file("libs/valdi_ota.json")
    stamp = layout.buildDirectory.file("valdi/codegen-check")
}
tasks.named("preBuild") { dependsOn(valdiCodegenCheck) }

androidComponents {
    val repo = rootProject.projectDir.parentFile
    @Suppress("UNCHECKED_CAST")
    val nativeInputs = (JsonSlurper().parse(repo.resolve("ota/fingerprint.json")) as Map<String, Any>)["android"] as List<String>
    onVariants { variant ->
        val info = tasks.register<ValdiOtaInfo>("${variant.name}ValdiOtaInfo") {
            exportInfo = file("libs/valdi_ota.json")
            fingerprintFiles.from(
                repo.resolve("scripts/ota.mjs"),
                repo.resolve("ota/fingerprint.json"),
                nativeInputs.map(repo::resolve),
                fileTree("generated/valdi"),
                fileTree(repo.resolve("valdi/modules")) { include("*/src/**", "*/module.json") },
                fileTree(repo.resolve("tools/valdi-rolldown")) {
                    include("module-bindings.ts", "codegen/**", "pipeline.ts", "valdiTs.ts")
                },
            )
            repoRoot = repo
            publicKey = repo.resolve("ota/public.pem")
            val version = variant.outputs.single().versionName.orNull ?: throw GradleException("The app has no versionName")
            appVersion = version
            // gradle.properties or -PvaldiOtaUrl=…; empty turns updates off. Debug builds never take them: they run the
            // modules they were built with, and pnpm dev's.
            val url = if (variant.buildType == "release") providers.gradleProperty("valdiOtaUrl").getOrElse("") else ""
            updateUrl = url
            if (url.isNotEmpty()) releaseRecord = repo.resolve("ota/releases/android/$version.json")
        }
        variant.sources.assets?.addGeneratedSourceDirectory(info, ValdiOtaInfo::outputDir)

        val modules = tasks.register<ValdiModules>("${variant.name}ValdiModules") {
            val tool = repo.resolve("tools/valdi-rolldown")
            sources.from(
                fileTree(repo.resolve("valdi/modules")) { include("*/src/**", "*/res/**", "*/sql/**", "*/tsconfig.json", "*/module.json", "*/BUILD.bazel") },
                fileTree(tool) { include("*.ts", "vendor/**", "package.json", "pnpm-lock.yaml") },
                repo.resolve("scripts/node-modules.mjs"),
                fileTree(repo.resolve("module-build")) { include("bzl/**", "MODULE.bazel", "MODULE.bazel.lock", ".bazelrc") },
                // The npm packages it bundles: their versions.
                repo.resolve("valdi/package.json"),
                repo.resolve("valdi/pnpm-lock.yaml"),
            )
            release = variant.buildType == "release"
            pnpm = providers.gradleProperty("valdiPnpm").map { listOf(it) }.orElse(
                if (System.getProperty("os.name").startsWith("Windows", ignoreCase = true)) {
                    listOf("node", repo.resolve("scripts/pnpm.mjs").path)
                } else {
                    listOf("pnpm")
                },
            )
            toolDir = tool
        }
        variant.sources.assets?.addGeneratedSourceDirectory(modules, ValdiModules::outputDir)
        variant.sources.res?.addGeneratedSourceDirectory(modules, ValdiModules::resDir)
        info.configure { dependsOn(modules) }
    }
}
